input.query:
WITH c AS (SELECT claim_id FROM claim WHERE peril='WINDSCREEN' AND YEAR(accident_date)=2024 AND report_date<=DATE '2025-12-31'),
t AS (SELECT ct.claim_id, SUM(CASE WHEN txn_type IN ('PAYMENT','RECOVERY') AND cost_type='INDEMNITY' THEN amount ELSE 0 END) paid_ind, SUM(CASE WHEN txn_type='RESERVE' AND cost_type='INDEMNITY' THEN amount ELSE 0 END) res FROM claim_txn ct JOIN c USING(claim_id) WHERE ct.txn_date<=DATE '2025-12-31' GROUP BY 1)
SELECT (SELECT COUNT(*) FROM c) n_claims, SUM(paid_ind) paid, SUM(res) reserve, SUM(paid_ind+res) reported_loss, (SELECT COUNT(*) FROM c) / 1 AS cnt, SUM(paid_ind+res)/(SELECT COUNT(*) FROM c) avg_per_claim, SUM(CASE WHEN res<>0 THEN 1 ELSE 0 END) claims_with_nonzero_reserve FROM t;
